mapper.select:
SELECT m.id AS merchant_id, m.category AS category, m.name, m.address, m.thumbnail_url, m.price, m.rating, COALESCE(COUNT(r.review_id), 0) AS review_count, 0 AS bookmarked FROM merchants m LEFT JOIN accommodations a ON a.merchant_id = m.id AND m.category = 'ACCOMMODATION' LEFT JOIN offices o ON o.merchant_id = m.id AND m.category = 'OFFICE' LEFT JOIN reviews r ON r.merchant_id = m.id AND r.status = 'ACTIVE' WHERE 1 = 1
AND m.category = 'ACCOMMODATION' AND a.merchant_id IS NOT NULL
AND m.category = 'OFFICE' AND o.merchant_id IS NOT NULL
AND ( ( m.category = 'ACCOMMODATION' AND a.merchant_id IS NOT NULL ) OR ( m.category = 'OFFICE' AND o.merchant_id IS NOT NULL ) )
AND m.region_id = #{regionId}
AND m.price >= #{minPrice}
AND m.price <= #{maxPrice}
AND EXISTS ( SELECT 1 FROM reservation_products rp INNER JOIN product_daily_inventories pdi ON pdi.product_id = rp.id WHERE rp.merchant_id = m.id AND ( ( m.category = 'ACCOMMODATION' AND rp.product_detail_type = 'ROOM'
AND rp.max_headcount >= #{headcount}
) OR ( m.category = 'OFFICE' AND rp.product_detail_type IN ('OFFICE_SEAT', 'MEETING_ROOM', 'PRIVATE_OFFICE')
AND ( ( rp.product_detail_type = 'OFFICE_SEAT' AND rp.max_headcount >= #{headcount} AND pdi.remaining_capacity >= #{headcount} ) OR ( rp.product_detail_type != 'OFFICE_SEAT' AND rp.max_headcount >= #{headcount} AND pdi.remaining_capacity > 0 ) )
) ) AND pdi.inventory_date >= #{checkInDate} AND ( (m.category = 'ACCOMMODATION' AND pdi.inventory_date < #{checkOutDate}) OR (m.category = 'OFFICE' AND pdi.inventory_date <= #{checkOutDate}) ) GROUP BY rp.id
HAVING COUNT(DISTINCT pdi.inventory_date) = CASE WHEN m.category = 'ACCOMMODATION' THEN #{requiredDateCount} WHEN m.category = 'OFFICE' THEN #{requiredDateCount} + 1 END AND MIN(CASE WHEN pdi.is_available = 1 AND pdi.remaining_capacity > 0 THEN 1 ELSE 0 END) = 1
HAVING COUNT(DISTINCT pdi.inventory_date) = CASE WHEN m.category = 'ACCOMMODATION' THEN #{requiredDateCount} WHEN m.category = 'OFFICE' THEN #{requiredDateCount} + 1 END AND MIN(CASE WHEN pdi.is_available = 1 AND ( (m.category = 'ACCOMMODATION' AND pdi.remaining_capacity >= #{headcount}) OR (m.category = 'OFFICE' AND ( (rp.product_detail_type = 'OFFICE_SEAT' AND rp.max_headcount >= #{headcount} AND pdi.remaining_capacity >= #{headcount}) OR (rp.product_detail_type != 'OFFICE_SEAT' AND rp.max_headcount >= #{headcount} AND pdi.remaining_capacity > 0) ) ) ) THEN 1 ELSE 0 END) = 1
)
GROUP BY m.id, m.category, m.name, m.address, m.thumbnail_url, m.price, m.rating
AND ( m.rating < #{cursorValue} OR ( m.rating = #{cursorValue} AND m.id < #{cursorMerchantId} ) )
ORDER BY m.rating DESC, m.id DESC
AND ( m.price > #{cursorValue} OR ( m.price = #{cursorValue} AND m.id > #{cursorMerchantId} ) )
ORDER BY m.price ASC, m.id ASC
ORDER BY m.rating DESC, m.id DESC
LIMIT #{size}

SELECT rp.id AS product_id, rp.product_name, rp.description, rp.product_detail_type, rp.max_headcount, rp.unit_price, rp.thumbnail_url FROM reservation_products rp
INNER JOIN product_daily_inventories pdi ON pdi.product_id = rp.id
WHERE rp.merchant_id = #{merchantId} AND rp.product_detail_type = 'ROOM'
AND rp.max_headcount * #{roomCount} >= #{headcount}
AND rp.max_headcount >= #{headcount}
AND pdi.inventory_date >= #{checkInDate} AND pdi.inventory_date < #{checkOutDate}
GROUP BY rp.id, rp.product_name, rp.description, rp.product_detail_type, rp.max_headcount, rp.unit_price, rp.thumbnail_url HAVING COUNT(DISTINCT pdi.inventory_date) = #{requiredDateCount} AND MIN(CASE WHEN pdi.is_available = 1 AND pdi.remaining_capacity >= #{requiredQuantity} THEN 1 ELSE 0 END) = 1
ORDER BY rp.id ASC
